/*
Grand Theft Autotoy Shoot 😈😈😈
__________________________________________
Accélérer : Flèche Haut ou W/Z
Freiner / Marche arrière : Flèche Bas ou S
Braquer à gauche : Flèche Gauche ou A/Q
Braquer à droite : Flèche Droite ou D
*/

// Nouveauté 19/09/26
// Amelioration graphique
// Ajout de voitures et de motos
// Ajout du systeme de Collision et explosion des voitures/motos en petits Pixels
mat2 rot(float a) {
    float c = cos(a), s = sin(a);
    return mat2(c, -s, s, c);
}

float hachage(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float bruit(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hachage(i), hachage(i + vec2(1.0, 0.0)), u.x),
               mix(hachage(i + vec2(0.0, 1.0)), hachage(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    mat2 r = rot(0.5);
    for (int i = 0; i < 4; i++) {
        v += a * bruit(p);
        p = r * p * 2.0 + vec2(100.0);
        a *= 0.5;
    }
    return v;
}

float distanceBoite(vec2 p, vec2 d) {
    vec2 q = abs(p) - d;
    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0);
}

float distanceBoiteArrondie(vec2 p, vec2 d, float r) {
    vec2 q = abs(p) - d + r;
    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}

vec3 obtenirSol(vec2 p) {
    vec2 grille = mod(p + 3.0, 6.0) - 3.0;
    vec2 cellule = floor((p + 3.0) / 6.0);
    float rX = abs(grille.x);
    float rY = abs(grille.y);
    float rMin = min(rX, rY);
    vec3 couleur = vec3(0.08, 0.09, 0.1);

    couleur -= fbm(p * 8.0) * 0.05;

    if (rMin >= 1.0 && rMin < 1.4) {
        couleur = mix(vec3(0.35, 0.35, 0.4), vec3(0.5, 0.5, 0.55), fbm(p * 15.0));
        vec2 tuile = fract(p * 2.0);
        if (tuile.x < 0.05 || tuile.y < 0.05) couleur *= 0.6;
        if (rMin < 1.05 || rMin > 1.35) couleur = vec3(0.18, 0.18, 0.2);
    } else if (rMin >= 1.4) {
        if (hachage(cellule) < 0.2) {
            couleur = mix(vec3(0.05, 0.2, 0.05), vec3(0.15, 0.35, 0.12), fbm(p * 20.0));
        } else {
            couleur = mix(vec3(0.15, 0.15, 0.17), vec3(0.25, 0.25, 0.28), fbm(p * 10.0));
        }
    } else {
        if (rX < 0.04 && rY > 1.4) {
            if (mod(p.y, 0.8) < 0.4) couleur = mix(couleur, vec3(0.9, 0.7, 0.1), 0.85);
        }
        if (rY < 0.04 && rX > 1.4) {
            if (mod(p.x, 0.8) < 0.4) couleur = mix(couleur, vec3(0.9, 0.7, 0.1), 0.85);
        }
        if (rX < 1.0 && rY < 1.0 && abs(rX - rY) < 0.05) {
            couleur += vec3(0.06);
        }
    }
    return couleur;
}

vec3 tonemapACES(vec3 x) {
    return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec4 etat = texelFetch(iChannel0, ivec2(0, 0), 0);
    vec2 positionVoiture = etat.xy;
    float angleVoiture = etat.z;
    float vitesse = etat.w;

    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float zoom = 7.5 - abs(vitesse) * 0.15;
    vec2 position = uv * zoom + positionVoiture;
    vec3 couleur = obtenirSol(position);
    float lissage = zoom / iResolution.y;

    for (int i = 1; i <= 8; i++) {
        vec4 pieton = texelFetch(iChannel0, ivec2(i, 0), 0);
        vec2 positionPieton = pieton.xy;
        float enVie = pieton.z;
        float id = pieton.w;
        vec2 decalage = position - positionPieton;
        float dist = length(decalage);

        if (enVie < 0.5) {
            float tache = fbm(position * 15.0 + id);
            float rayonSang = 0.35 + sin(id * 10.0) * 0.15;
            if (dist < rayonSang && tache > 0.35) {
                float opacite = smoothstep(rayonSang, rayonSang - 0.1, dist);
                couleur = mix(couleur, vec3(0.35, 0.01, 0.02), opacite * 0.9);
            }
        } else {
            float dCorps = dist - 0.12;
            float dTete = dist - 0.07;
            vec3 colPieton = mix(vec3(0.15, 0.25, 0.35), vec3(0.7, 0.5, 0.3), smoothstep(0.01, -0.01, dCorps));
            colPieton = mix(colPieton, vec3(0.85, 0.65, 0.55), smoothstep(0.01, -0.01, dTete));
            couleur = mix(couleur, colPieton, smoothstep(lissage, -lissage, dCorps));
        }
    }

    for (int i = 0; i < 8; i++) {
        vec4 trafic = texelFetch(iChannel0, ivec2(i, 1), 0);
        float tV = trafic.w;
        vec2 pV = trafic.xy;
        float id = float(i);

        if (tV < 0.0) {
            bool isMoto = tV < -1.5;
            float tempsEcoule = iTime - trafic.z;

            if (tempsEcoule < 3.0) { 
                vec2 posImpact = pV;
                float vitesseExpansion = 12.0; 

                if (tempsEcoule < 0.5) {
                    float flashIntensite = smoothstep(0.5, 0.0, tempsEcoule);
                    float dCentre = distanceBoiteArrondie(position - posImpact, vec2(0.01), 0.01);
                    couleur += vec3(1.0, 0.9, 0.5) * flashIntensite * smoothstep(lissage, -lissage, dCentre) * 5.0;
                }

                for (int p = 0; p < 32; p++) {
                    float idParticule = float(p);
                    float angleParticule = hachage(vec2(id, idParticule)) * 6.28318;
                    float vitesseRandom = 0.5 + hachage(vec2(idParticule, id)) * 1.5;
                    float rayon = tempsEcoule * vitesseExpansion * vitesseRandom;

                    vec2 posParticule = posImpact + vec2(cos(angleParticule), sin(angleParticule)) * rayon;

                    float dParticule = distanceBoite(position - posParticule, vec2(0.008));
                    float intensitePixel = smoothstep(lissage, -lissage, dParticule);

                    if (intensitePixel > 0.0) {
                        float intensiteDisparition = smoothstep(3.0, 0.0, tempsEcoule);
                        vec3 colParticule = vec3(0.0);


                        float typeCouleur = hachage(vec2(angleParticule, vitesseRandom));
                        if (isMoto) {
                            if (typeCouleur < 0.4) colParticule = vec3(1.0, 0.2, 0.1); 
                            else if (typeCouleur < 0.8) colParticule = vec3(0.1, 0.7, 0.2); 
                            else colParticule = vec3(1.0, 0.5, 0.0); 
                        } else {
                            if (typeCouleur < 0.2) colParticule = vec3(1.0, 0.2, 0.1); 
                            else if (typeCouleur < 0.4) colParticule = vec3(0.2, 0.4, 0.8); 
                            else if (typeCouleur < 0.6) colParticule = vec3(0.9, 0.6, 0.1); 
                            else if (typeCouleur < 0.8) colParticule = vec3(0.8);
                            else colParticule = vec3(1.0, 0.5, 0.0); 
                        }

                        couleur = mix(couleur, colParticule * (1.0 + smoothstep(1.0, 0.0, tempsEcoule)*2.0), intensitePixel * intensiteDisparition * 0.9);
                    }
                }
            }
        } else { 
            vec2 pL = (position - pV) * rot(-trafic.z);

            if (tV > 0.5) {
                if (pL.x > 0.1 && pL.x < 3.5) {
                    float ecart = pL.x * 0.4;
                    if (abs(pL.y) < ecart) {
                        float intensite = smoothstep(3.5, 0.1, pL.x) * smoothstep(ecart, ecart - 0.2, abs(pL.y));
                        couleur += vec3(1.0, 0.95, 0.8) * intensite * 0.8;
                    }
                }
                float dOmbreM = distanceBoiteArrondie(pL - vec2(-0.04, -0.06), vec2(0.16, 0.06), 0.03);
                couleur = mix(couleur * 0.3, couleur, smoothstep(-0.05, 0.1, dOmbreM));
                float dMoto = distanceBoiteArrondie(pL, vec2(0.16, 0.06), 0.03);
                vec3 colM = vec3(0.9, 0.1, 0.1);
                if (i == 3 || i == 7) colM = vec3(0.1, 0.7, 0.2);
                couleur = mix(couleur, colM, smoothstep(lissage, -lissage, dMoto));
                float dPilote = length(pL - vec2(0.02, 0.0)) - 0.08;
                couleur = mix(couleur, vec3(0.15), smoothstep(lissage, -lissage, dPilote));
                float dCasque = length(pL - vec2(0.05, 0.0)) - 0.06;
                couleur = mix(couleur, vec3(0.9, 0.8, 0.1), smoothstep(lissage, -lissage, dCasque));
            } else { 
                if (pL.x > 0.3 && pL.x < 4.0) {
                    float ecart = pL.x * 0.6;
                    if (abs(pL.y) < ecart) {
                        float intensite = smoothstep(4.0, 0.3, pL.x) * smoothstep(ecart, ecart - 0.4, abs(pL.y));
                        couleur += vec3(1.0, 0.9, 0.7) * intensite * 0.8;
                    }
                }
                float dOmbreV = distanceBoiteArrondie(pL - vec2(-0.06, -0.12), vec2(0.42, 0.22), 0.1);
                couleur = mix(couleur * 0.25, couleur, smoothstep(-0.05, 0.2, dOmbreV));
                float dCarr = distanceBoiteArrondie(pL, vec2(0.38, 0.18), 0.06);
                vec3 colV = vec3(0.8, 0.8, 0.8);
                if (i == 0 || i == 4) colV = vec3(0.8, 0.2, 0.2);
                if (i == 1 || i == 5) colV = vec3(0.2, 0.4, 0.8);
                if (i == 2 || i == 6) colV = vec3(0.9, 0.6, 0.1);
                float dCab = distanceBoiteArrondie(pL - vec2(-0.03, 0.0), vec2(0.20, 0.14), 0.04);
                colV = mix(colV, vec3(0.05), smoothstep(lissage, -lissage, dCab));
                float dPB = distanceBoite(pL - vec2(0.12, 0.0), vec2(0.04, 0.12));
                colV = mix(colV, vec3(0.15, 0.35, 0.55), smoothstep(lissage, -lissage, dPB));
                float dVA = distanceBoite(pL - vec2(-0.16, 0.0), vec2(0.03, 0.11));
                colV = mix(colV, vec3(0.15, 0.3, 0.5), smoothstep(lissage, -lissage, dVA));
                float dPhA = min(distanceBoite(pL - vec2(0.35, 0.14), vec2(0.04, 0.03)), distanceBoite(pL - vec2(0.35, -0.14), vec2(0.04, 0.03)));
                colV = mix(colV, vec3(1.0, 1.0, 0.9), smoothstep(lissage, -lissage, dPhA));
                float dPhAr = min(distanceBoite(pL - vec2(-0.36, 0.14), vec2(0.03, 0.04)), distanceBoite(pL - vec2(-0.36, -0.14), vec2(0.03, 0.04)));
                colV = mix(colV, vec3(0.4, 0.0, 0.0), smoothstep(lissage, -lissage, dPhAr));
                couleur = mix(couleur, colV, smoothstep(lissage, -lissage, dCarr));
            }
        }
    }

    vec2 positionLoc = (position - positionVoiture) * rot(-angleVoiture);

    vec3 lumierePhares = vec3(0.0);
    if (positionLoc.x > 0.3 && positionLoc.x < 5.0) {
        float ecart = positionLoc.x * 0.6;
        if (abs(positionLoc.y) < ecart) {
            float intensite = smoothstep(5.0, 0.3, positionLoc.x) * smoothstep(ecart, ecart - 0.5, abs(positionLoc.y));
            lumierePhares = vec3(1.0, 0.95, 0.8) * intensite * 1.2;
            couleur += lumierePhares;
        }
    }

    float dOmbreV = distanceBoiteArrondie(positionLoc - vec2(-0.06, -0.12), vec2(0.42, 0.22), 0.1);
    couleur = mix(couleur * 0.25, couleur, smoothstep(-0.05, 0.2, dOmbreV));

    float dCarrosserie = distanceBoiteArrondie(positionLoc, vec2(0.38, 0.18), 0.06);
    vec3 colVoiture = vec3(0.1, 0.45, 0.85);
    float reflet = fbm(positionLoc * 15.0 - vec2(iTime * 0.2));
    colVoiture += vec3(0.3) * smoothstep(0.4, 0.7, reflet);

    float dCabine = distanceBoiteArrondie(positionLoc - vec2(-0.03, 0.0), vec2(0.20, 0.14), 0.04);
    colVoiture = mix(colVoiture, vec3(0.05, 0.05, 0.06), smoothstep(lissage, -lissage, dCabine));

    float dPareBrise = distanceBoite(positionLoc - vec2(0.12, 0.0), vec2(0.04, 0.12));
    colVoiture = mix(colVoiture, vec3(0.15, 0.35, 0.55), smoothstep(lissage, -lissage, dPareBrise));

    float dVitreArriere = distanceBoite(positionLoc - vec2(-0.16, 0.0), vec2(0.03, 0.11));
    colVoiture = mix(colVoiture, vec3(0.15, 0.3, 0.5), smoothstep(lissage, -lissage, dVitreArriere));

    float dPhareAv = min(distanceBoite(positionLoc - vec2(0.35, 0.14), vec2(0.04, 0.03)), distanceBoite(positionLoc - vec2(0.35, -0.14), vec2(0.04, 0.03)));
    colVoiture = mix(colVoiture, vec3(1.0, 1.0, 0.9), smoothstep(lissage, -lissage, dPhareAv));

    float dPhareAr = min(distanceBoite(positionLoc - vec2(-0.36, 0.14), vec2(0.03, 0.04)), distanceBoite(positionLoc - vec2(-0.36, -0.14), vec2(0.03, 0.04)));
    vec3 colFeuAr = vitesse < -0.02 ? vec3(1.0, 0.2, 0.1) : vec3(0.4, 0.0, 0.0);
    colVoiture = mix(colVoiture, colFeuAr, smoothstep(lissage, -lissage, dPhareAr));

    couleur = mix(couleur, colVoiture, smoothstep(lissage, -lissage, dCarrosserie));

    vec2 cellule = floor((position + 3.0) / 6.0);
    vec2 centreBloc = cellule * 6.0;
    float hCellule = hachage(cellule);

    if (hCellule >= 0.2) {
        float hauteur = 0.8 + hCellule * 1.5;
        vec2 centreOmbre = centreBloc + vec2(0.5, -0.5) * hauteur;
        float dOmbreBat = distanceBoite(position - centreOmbre, vec2(1.5));
        float dBase = distanceBoite(position - centreBloc, vec2(1.5));

        if (dBase > 0.0) {
            couleur = mix(couleur * 0.35, couleur, smoothstep(0.0, 0.4, dOmbreBat));
        }

        vec2 decToit = (centreBloc - positionVoiture) * (hauteur * 0.12);
        vec2 centreToit = centreBloc + decToit;
        float dToit = distanceBoiteArrondie(position - centreToit, vec2(1.5), 0.02);

        vec2 dir = centreToit - centreBloc;
        float lDir = length(dir);
        if (lDir > 0.001) {
            vec2 norm = dir / lDir;
            float cote = dot(position - centreBloc, vec2(-norm.y, norm.x));
            float proj = dot(position - centreBloc, norm);
            if (proj >= 0.0 && proj <= lDir && abs(cote) <= 1.5) {
                float ecl = 0.4 + 0.6 * max(0.0, dot(norm, normalize(vec2(1.0, 1.0))));
                couleur = vec3(0.12, 0.11, 0.13) * ecl;
            }
        }

        if (dToit < 0.0) {
            vec3 colToit = vec3(0.22, 0.24, 0.26) * (0.8 + 0.3 * fbm(position * 6.0));
            float dBordure = distanceBoite(position - centreToit, vec2(1.42));
            colToit = mix(colToit * 0.5, colToit, smoothstep(0.0, lissage * 2.0, dBordure));
            float dClim = distanceBoite(position - centreToit - vec2(0.5, -0.4), vec2(0.3, 0.2));
            colToit = mix(vec3(0.4, 0.38, 0.35), colToit, smoothstep(0.0, lissage, dClim));
            couleur = colToit;
        }
    }

    couleur *= 1.0 - 0.4 * dot(uv, uv);
    couleur = tonemapACES(couleur);

    fragColor = vec4(couleur, 1.0);
}

bool obtenirTouche(int codeTouche) {
    return texelFetch(iChannel0, ivec2(codeTouche, 0), 0).x > 0.5;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    ivec2 positionPixel = ivec2(fragCoord);

    if (positionPixel.y > 1 || positionPixel.x > 8) {
        fragColor = vec4(0.0);
        return;
    }

    if (positionPixel.y == 0) {
        if (positionPixel.x == 0) {
            vec4 etatVoiture = texelFetch(iChannel1, ivec2(0, 0), 0);
            vec2 positionVoiture = etatVoiture.xy;
            float angleVoiture = etatVoiture.z;
            float vitesseVoiture = etatVoiture.w;

            if (iFrame == 0) {
                positionVoiture = vec2(0.0);
                angleVoiture = 0.0;
                vitesseVoiture = 0.0;
            }

            float deltaTemps = min(iTimeDelta, 0.05);

            bool toucheHaut = obtenirTouche(38) || obtenirTouche(87);
            bool toucheBas = obtenirTouche(40) || obtenirTouche(83);
            bool toucheGauche = obtenirTouche(37) || obtenirTouche(65);
            bool toucheDroite = obtenirTouche(39) || obtenirTouche(68);

            if (toucheHaut) vitesseVoiture += 9.0 * deltaTemps;
            if (toucheBas) vitesseVoiture -= 7.0 * deltaTemps;

            vitesseVoiture *= pow(0.015, deltaTemps);

            if (abs(vitesseVoiture) > 0.02) {
                float sensDeplacement = vitesseVoiture > 0.0 ? 1.0 : -1.0;
                float forceBraquage = clamp(abs(vitesseVoiture) * 0.4, 0.0, 1.0);
                if (toucheGauche) angleVoiture += 3.8 * sensDeplacement * forceBraquage * deltaTemps;
                if (toucheDroite) angleVoiture -= 3.8 * sensDeplacement * forceBraquage * deltaTemps;
            }

            positionVoiture += vec2(cos(angleVoiture), sin(angleVoiture)) * vitesseVoiture * deltaTemps;
            fragColor = vec4(positionVoiture, angleVoiture, vitesseVoiture);
            return;
        }

        vec4 etatPieton = texelFetch(iChannel1, positionPixel, 0);
        float identifiantPieton = float(positionPixel.x);

        if (iFrame == 0) {
            vec2 positionInitiale = vec2(
                mod(identifiantPieton * 2.3, 10.0) - 5.0,
                1.2 * (mod(identifiantPieton, 2.0) == 0.0 ? 1.0 : -1.0) + floor(identifiantPieton / 2.0) * 2.5 - 3.5
            );
            etatPieton = vec4(positionInitiale, 1.0, identifiantPieton);
        } else {
            vec4 voiture = texelFetch(iChannel1, ivec2(0, 0), 0);
            vec2 positionVoiturePieton = voiture.xy;

            if (etatPieton.z > 0.5) {
                float deltaTemps = min(iTimeDelta, 0.05);
                float directionPieton = mod(etatPieton.w, 2.0) > 0.5 ? 1.0 : -1.0;
                etatPieton.x += directionPieton * 1.2 * deltaTemps;

                if (abs(etatPieton.x) > 8.0) etatPieton.x = -etatPieton.x;

                if (distance(etatPieton.xy, positionVoiturePieton) < 0.48) {
                    etatPieton.z = 0.0;
                }
            }
        }
        fragColor = etatPieton;
        return;
    }

    if (positionPixel.y == 1) {
        vec4 etatTrafic = texelFetch(iChannel1, positionPixel, 0);
        float id = float(positionPixel.x);

        if (iFrame == 0) {
            float typeRoute = floor(id / 2.0);
            float dec = mod(id, 2.0) * 16.0 - 8.0;
            float isMoto = mod(id, 3.0) == 0.0 ? 1.0 : 0.0;

            if (typeRoute == 0.0) etatTrafic = vec4(dec, -0.45, 0.0, isMoto);
            else if (typeRoute == 1.0) etatTrafic = vec4(dec, 0.45, 3.14159, isMoto);
            else if (typeRoute == 2.0) etatTrafic = vec4(0.45, dec, 1.57079, isMoto);
            else etatTrafic = vec4(-0.45, dec, -1.57079, isMoto);
        } else if (etatTrafic.w >= 0.0) { 
            vec4 voiture = texelFetch(iChannel1, ivec2(0, 0), 0);
            vec2 positionJoueur = voiture.xy;

            if (distance(etatTrafic.xy, positionJoueur) < 0.5) {
                etatTrafic = vec4(etatTrafic.xy, iTime, -etatTrafic.w - 1.0);
            } else {
                float dt = min(iTimeDelta, 0.05);
                float v = etatTrafic.w > 0.5 ? 5.5 : 3.5;
                etatTrafic.xy += vec2(cos(etatTrafic.z), sin(etatTrafic.z)) * v * dt;

                if (etatTrafic.x > 30.0) etatTrafic.x -= 60.0;
                if (etatTrafic.x < -30.0) etatTrafic.x += 60.0;
                if (etatTrafic.y > 30.0) etatTrafic.y -= 60.0;
                if (etatTrafic.y < -30.0) etatTrafic.y += 60.0;
            }
        }
        fragColor = etatTrafic;
        return;
    }
}
